1237: function gameLoop(now) {
1238:   // 1. Update water & flower tile animation counter every 280ms (matching ~20 Game Boy frames)
1239:   if (now - lastAnimTick > 280) {
1240:     lastAnimTick = now;
1241:     engine.animCounter = (engine.animCounter + 1) & 7;
1242:     if (state.dialogue && state.dialogue.pikachuMood) {
