1246: 
1247:   // 2. Update Player smooth step interpolation
1248:   if (state.player.moveAnim) {
1249:     const anim = state.player.moveAnim;
1250:     const t = Math.min(1, (now - anim.startTime) / anim.duration);
1251:     state.player.renderX = anim.fromX + (anim.toX - anim.fromX) * t;
1252:     let jumpArc = 0;
1253:     if (anim.isLedgeJump) {
1254:       jumpArc = -Math.sin(t * Math.PI) * 0.75;
1255:     }
1256:     state.player.renderY = anim.fromY + (anim.toY - anim.fromY) * t + jumpArc;
1257: 
1258:     if (state.pikachu.moveAnim) {
1259:       const pa = state.pikachu.moveAnim;
1260:       state.pikachu.renderX = pa.fromX + (pa.toX - pa.fromX) * t;
1261:       state.pikachu.renderY = pa.fromY + (pa.toY - pa.fromY) * t;
1262:     }
1263: 
1264:     if (t >= 1) {
1265:       state.player.x = anim.toX;
1266:       state.player.y = anim.toY;
1267:       state.player.renderX = anim.toX;
1268:       state.player.renderY = anim.toY;
1269:       state.player.walking = false;
1270:       state.player.moveAnim = null;
1271: 
1272:       if (state.pikachu.moveAnim) {
1273:         state.pikachu.x = state.pikachu.moveAnim.toX;
1274:         state.pikachu.y = state.pikachu.moveAnim.toY;
1275:         state.pikachu.renderX = state.pikachu.x;
1276:         state.pikachu.renderY = state.pikachu.y;
