1283:   } else if (heldDirs.size > 0 && !state.dialogue && !state.battle) {
1284:     const lastDir = Array.from(heldDirs).pop();
1285:     attemptStep(lastDir);
1286:   }
1287: 
1288:   // 3. Gentle NPC wander for WALK NPCs
1289:   if (now - lastNpcTick > 1600 && !state.dialogue && !state.battle) {
1290:     lastNpcTick = now;
1291:     for (const npc of state.npcs) {
1292:       if (npc.movement !== "WALK" || npc.isWalking) continue;
1293:       if (!npc.defaultVisible && !state.showHiddenObjects) continue;
1294:       if (Math.random() < 0.35) {
1295:         const dirs =
1296:           npc.dir === "UP_DOWN"
1297:             ? ["UP", "DOWN"]
1298:             : npc.dir === "LEFT_RIGHT"
1299:             ? ["LEFT", "RIGHT"]
1300:             : ["DOWN", "UP", "LEFT", "RIGHT"];
1301:         const d = dirs[Math.floor(Math.random() * dirs.length)];
1302:         npc.facing = d;
1303:         const dx = d === "LEFT" ? -1 : d === "RIGHT" ? 1 : 0;
1304:         const dy = d === "UP" ? -1 : d === "DOWN" ? 1 : 0;
1305:         const nx = npc.x + dx;
1306:         const ny = npc.y + dy;
1307:         if (
1308:           Math.abs(nx - npc.originX) <= 2 &&
1309:           Math.abs(ny - npc.originY) <= 2 &&
1310:           nx >= 0 &&
1311:           nx < state.currentZone.width * 2 &&
1312:           ny >= 0 &&
1313:           ny < state.currentZone.height * 2 &&
1314:           !(nx === state.player.x && ny === state.player.y) &&
1315:           !(nx === state.pikachu.x && ny === state.pikachu.y) &&
1316:           engine.isStepPassable(state.currentZone, npc.x, npc.y, nx, ny)
1317:         ) {
1318:           npc.x = nx;
1319:           npc.y = ny;
1320:           npc.renderX = nx;
1321:           npc.renderY = ny;
1322:           npc.stepParity = !npc.stepParity;
1323:         }
1324:       }
1325:     }
