62:         pixels: unpack2Bit(v.data, v.width, v.height),
63:       };
64:     }
65:     this.spriteConstToKey = data.sprites.constToKey;
66: 
67:     this.pikachuFaces = {};
68:     for (const [k, v] of Object.entries(data.sprites.pikachuFaces)) {
69:       this.pikachuFaces[k] = {
70:         width: v.width,
71:         height: v.height,
72:         pixels: unpack2Bit(v.data, v.width, v.height),
73:       };
74:     }
75: 
76:     this.emotes = {};
77:     for (const [k, v] of Object.entries(data.sprites.emotes)) {
78:       this.emotes[k] = {
79:         width: v.width,
80:         height: v.height,
81:         pixels: unpack2Bit(v.data, v.width, v.height),
82:       };
83:     }
84: 
85:     this.pokemonSprites = {};
86:     for (const [k, v] of Object.entries(data.sprites.pokemon)) {
87:       this.pokemonSprites[k] = {
88:         width: v.width,
89:         height: v.height,
90:         pixels: unpack2Bit(v.data, v.width, v.height),
91:       };
92:     }
