94:     // Index all zones
95:     this.allZones = data.zones.map((z) => ({
96:       ...z,
97:       blockBytes: unpackBytes(z.blocks),
98:     }));
99:     this.canonicalZones = this.allZones.filter((z) => z.isCanonical220);
100:     this.zonesByConst = {};
101:     this.zonesByNumber = {};
102:     this.zonesByRomId = {};
103:     for (const z of this.allZones) {
104:       this.zonesByConst[z.constName] = z;
105:       this.zonesByNumber[z.zoneNumber] = z;
106:       if (!this.zonesByRomId[z.romId]) this.zonesByRomId[z.romId] = z;
107:     }
