.hp-bar-Row {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 2px;
}

.hp-tag {
  font-size: 8.5px;
  font-weight: 800;
}

.hp-track {
  flex: 1;
  height: 6px;
  background: #e2e8f0;
  border: 1px solid #111827;
