import("./src/data/pokeyellow-data.js").then(async ({ POKEYELLOW_DATA }) => {
  const { PokeYellowEngine } = await import("./src/engine.js");
  const eng = new PokeYellowEngine(POKEYELLOW_DATA);
  for (const zname of ["VIRIDIAN_POKECENTER", "INDIGO_PLATEAU_LOBBY", "REDS_HOUSE_2F", "OAKS_LAB", "CELADON_HOTEL"]) {
    const z = eng.zonesByConst[zname];
    console.log("===", zname, z.width*2, "x", z.height*2, "tileset:", z.tileset, "===");
    for (let y = 0; y < z.height * 2; y++) {
      let row = [];
      for (let x = 0; x < z.width * 2; x++) {
        const t = eng.getCollisionTileAtStep(z, x, y);
        const topT = eng.getTileIdAt8x8(z, x*2, y*2);
        row.push(`${x},${y}:$${t.toString(16).padStart(2,"0")}/$${topT.toString(16).padStart(2,"0")}`);
      }
      if (y <= 5) console.log(" y=" + y + ":", row.join(" "));
    }
  }
});
'

